    ou: (nom, f, t) => `Votre mise en route pour ${nom} en est à ${f} sur ${t}.`, reste: n => n > 1 ? "Il reste ces étapes :" : "Il reste cette étape :", bouton: "Terminer ma mise en route",
    deja: "Déjà fait ? Dites-le dans votre espace, sur l'accueil : BoostImpact vérifie et vous n'aurez plus ce rappel." },
