// Étapes de la mise en route, numérotées dans l'ordre de l'espace (1 à 4, ou 1 à 3 sans réseaux) : [{numero, titre, aide}].
const etapesNumerotees = (cles, P, ordre = ORDRE_POINTS) => cles.map(k => ({ numero: String(ordre.indexOf(k) + 1), titre: P[k].titre, aide: P[k].aide }));
const etapesTexte = e => e.flatMap(x => [`${x.numero}. ${x.titre}`, `   ${x.aide}`]);
// 27/10/2026 (audit du parcours, constats 16 et 17) : la bienvenue part 3 secondes après l'invitation de Supabase (même workflow) ; elle dit
// précisément quel email ouvrir et sur quel bouton cliquer (titres d'espace/supabase/emails/invitation.html, désormais dans la langue du commerce
// dès la première invitation), et quoi faire si le lien a expiré (page de connexion, i18n.js acc.oubli). Clés regle1 et regle2 (trois offres dans
// la même phrase) gardées pour mémoire, plus affichées.
// commerce : { nom, email, langue, offre_id, origine }. offre_id : offre du commerce (absente : avec réseaux, 4 étapes, comme avant le 26/10/2026).
// origine « paiement_en_ligne » (journal COMMERCE_CREE écrit par client_en_ligne) : objet « Bienvenue chez BoostImpact : vos N étapes… ».
function bienvenueEmail(commerce, ctx) {
  const lg = langueEmail(commerce.langue), T = TEXTES_ACCUEIL[lg], C = COMMUN[lg], P = POINTS_LANGUES[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const nom = nettoyerNom(commerce.nom), url = adresse(ctx.urlEspace);
  // Sans nom, l'email partait « Bienvenue chez BoostImpact, » (18/10/2026 : réponse de la base lue comme du texte par n8n) : refusé ici,
  // le workflow d'erreur prévient PJ au lieu d'envoyer un email à trou.
  if (!nom) throw new Error("nom du commerce absent : email de bienvenue non rédigé");
  const ordre = pointsOffre(commerce.offre_id), n = ordre.length, google = !avecReseaux(commerce.offre_id);
  const sujet = commerce.origine === "paiement_en_ligne" ? T.sujetAchat(n) : T.sujet(nom, n), etapes = etapesNumerotees(ordre, P, ordre);
  // 27/10/2026 (audit du parcours, constat 17) : seulement les règles de l'offre du client (CGV, articles 8 et 9) ; plus de phrase qui explique les trois
  // offres. Premium : la délégation, à choisir à la mise en route ; toute autre offre avec réseaux (Croissance, ancienne offre) : celles de la Croissance.
  const role = google ? T.roleGoogle(n, PUBLICATIONS_GOOGLE[commerce.offre_id] || PUBLICATIONS_GOOGLE.essentiel) : T.role(n);
  // 29/10/2026 (décision de PJ) : l'Essentiel a la même règle des avis que Croissance et Premium (moteur/offres.json : avis_auto, avis_equipe) ;
  // regle2Google et regle2 (« chaque réponse attend votre accord ») retirées (lot 3a) : contraires aux CGV art. 8, plus affichées depuis le 29/10/2026.
  const regle1 = google ? T.regle1Google : commerce.offre_id === "premium" ? T.regle1Premium : T.regle1Croissance, regle2 = T.regle2Equipe;
  // Lot 5a (15/11/2026, CGV art. 10) : les délais garantis, dont la première publication sous 72 h en Croissance et Premium (départ : accès à la fiche
  // et premières photos ; en Essentiel, l'accès seul). Sans « garantie » ni « offert » (email transactionnel, 24/10/2026).
  const delais = google ? T.delais : T.delaisReseaux;
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(n), h1: T.h1(nom), chapo: T.chapo(n),
    corps: [M.p(echapper(C.bonjour), { couleur: M.C.texte }), M.p(echapper(T.premier), { marge: "0 0 6px 0", couleur: M.C.texte, style: "font-weight:600" }), M.p(echapper(T.connexion), { marge: "0 0 28px 0" }),
      M.h2(T.etapes(n), "0 0 8px 0"), M.p(echapper(T.suivi), { taille: 15, couleur: M.C.texteDiscret }), M.etapes(etapes), M.bouton(url, C.ouvrir),
      M.h2(T.relais), M.p(echapper(role)), M.p(echapper(regle1)), M.p(echapper(regle2)), M.p(echapper(delais), { marge: "0 0 24px 0" })],
    pied: [T.raison(nom)] });
  const texte = [C.bonjour, "", T.chapo(n), "", T.premier + " " + T.connexion, "", T.etapes(n), "", ...etapesTexte(etapes), "", C.ouvrir + C.sep + url, "",
    T.relais, role, regle1, regle2, delais, "",
    mots.question, mots.equipe, "", T.raison(nom)].join("\n");
  return { destinataire: commerce.email, sujet, html, texte: avecPied(texte, lg) };
}
