const lienAvisEmail = (url, jetonAvis, jetonEnvoi, lg) => adresse(url, avecLangue("/avis.html?source=email&envoi=" + encodeURIComponent(jetonEnvoi) + "#" + jetonAvis, lg));   // lot 1 : ?lang= (en, nl)
