const nettoyerNom = s => String(s == null ? "" : s).replace(/["<>\r\n]/g, "").trim();
// Bouton de page() (demande d'avis, prospection) : « à l'épreuve des clients mail » (cellule colorée et lien en bloc), aplat vert du logo, texte encre
