    rienAttente: "Rien n'attend votre validation.", sujet: (m, n) => `Votre bilan ${deMois(m)}, ${n}`,
    h1: m => `Votre bilan ${deMois(m)}.`, chapo: n => `Ce que nous avons fait pour ${n}, ce qui évolue et ce que nous améliorons.`,
    apercu: (r, p) => `${pluriel(r, "réponse publiée", "réponses publiées")} à vos avis, ${pluriel(p, "publication parue", "publications parues")}. Le détail du mois et la suite.`,
    fReponses: "Réponses aux avis", fPublications: "Publications", fNote: m => "Note Google au " + m,
    explicationGoogle: "Note et avis : calculés au moment de ce bilan à partir des avis présents sur votre fiche Google (un avis supprimé depuis n'est pas compté). Google ne permet pas à BoostImpact de les conserver.",
    explicationBase: "Avis obtenus : avis arrivés dans BoostImpact ce mois-ci. Votre fiche Google n'a pas pu être lue au moment de ce bilan : la note n'est pas donnée.",
    bonjour: "Bonjour,", voici: (m, n) => `Voici le bilan ${deMois(m)} pour ${n}.`, fait: "Ce que nous avons fait.", evolue: "Ce qui évolue.", disent: "Ce que disent vos avis ce mois-ci.",
    ameliorons: "Ce que nous améliorons le mois prochain.", aide: "Aide Google", ouvrir: "Ouvrir mon espace", valider: "Valider dans mon espace", source: " Source : ", espace: "Votre espace : ",
    pied: "Vous recevez ce bilan une fois par mois. Pour ne plus le recevoir, décochez l'email dans les réglages de votre espace.", hl: "fr" },
  en: { nonLue: "not read", note: v => v + " out of 5", nonLus: "not read", avisBase: n => n + " (received and tracked by BoostImpact)", reponses: "Review replies published", publications: "Posts published",
    noteAu: m => "Google rating on " + m, avisMois: "Reviews received during the month", appels: "Clicks on your profile's call button", itineraires: "Direction requests",
    clicsSite: "Clicks to your website", vues: "Views of your profile (Google Maps and Search)", reservations: "Bookings made from your profile (Reserve with Google)",
    perfNote: "These figures are Google's. A click is not a completed call, nor a visit: Google counts the click on the call button, not the call itself; a direction request is not a visit.",
    compte: (p, n) => `${p} positive mention${p === 1 ? "" : "s"}, ${n} negative`,
    baisse: "Your rating dropped this month: we will go over the negative reviews and our replies with you.",
    themesNegatifs: neg => `Theme${neg.length > 1 ? "s" : ""} recurring in negative reviews: ${neg.join(", ")}. We will discuss this with you before the next summary.`,
    rythme: "We keep up the pace: every new review handled within 24 hours, your posts for the month proposed on time.",
    attente: a => pluriel(a, "post is", "posts are") + " awaiting your approval.", attenteSuite: a => a > 1 ? "Once approved, they will be published." : "Once approved, it will be published.",
    rienAttente: "Nothing is awaiting your approval.", sujet: (m, n) => `Your ${m} summary, ${n}`,
    h1: m => `Your ${m} summary.`, chapo: n => `What we did for ${n}, what is changing and what we are improving.`,
    apercu: (r, p) => `${pluriel(r, "review reply", "review replies")} published, ${pluriel(p, "post", "posts")} published. The month in detail and what comes next.`,
