const etatPourEquipe = r => r.point === "metricool" && r.etat === "a_faire" && "lien_envoye_le" in r ? (r.lien_envoye_le ? `à faire par le commerçant (lien envoyé le ${dateLettres(r.lien_envoye_le)})` : "lien de connexion à envoyer par l'équipe, puis noter « Lien envoyé » dans la console")
