// Heure annoncée (« demain à 11 h », « le 18 novembre à 11 h ») : celle de la base (pas_avant), heure de Paris.
function quandAnnonce(iso, lg, ctx) {
  const d = new Date(iso); if (!iso || isNaN(d)) return "";
  const now = ctx && ctx.maintenant ? new Date(ctx.maintenant) : new Date(), tz = "Europe/Paris";
  const jour = x => new Intl.DateTimeFormat("en-CA", { timeZone: tz }).format(x), h = new Intl.DateTimeFormat("fr-FR", { timeZone: tz, hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(d);
  const hh = +h.find(p => p.type === "hour").value, mm = h.find(p => p.type === "minute").value;
  const heure = lg === "en" ? new Intl.DateTimeFormat("en-GB", { timeZone: tz, hour: "numeric", minute: "2-digit", hour12: true }).format(d).replace(":00", "").replace(" ", " ")
    : lg === "nl" ? `${hh}.${mm} uur`.replace(".00 uur", " uur") : `${hh} h${mm === "00" ? "" : " " + mm}`;
  const j0 = jour(now), j1 = jour(new Date(now.getTime() + 864e5)), jd = jour(d);
  const date = new Intl.DateTimeFormat({ fr: "fr-FR", en: "en-GB", nl: "nl-BE" }[lg], { timeZone: tz, day: "numeric", month: "long" }).format(d);
  if (lg === "en") return jd === j0 ? `today at ${heure}` : jd === j1 ? `tomorrow at ${heure}` : `on ${date} at ${heure}`;
  if (lg === "nl") return jd === j0 ? `vandaag om ${heure}` : jd === j1 ? `morgen om ${heure}` : `op ${date} om ${heure}`;
  return jd === j0 ? `aujourd'hui à ${heure}` : jd === j1 ? `demain à ${heure}` : `le ${date} à ${heure}`;
}

