// Lot 4a (15/11/2026, CGV art. 8 : toutes les offres, l'équipe publie les réponses aux avis sans accord préalable) : plus d'alerte « avis_a_valider »
// (qui demandait au commerçant de valider la réponse) ; une ancienne alerte de ce type n'est pas rédigée (canal « aucun »,
// n8n/build_whatsapp.py). Avis sensible : une seule version, celle où l'équipe publie (« sous 24 h », art. 9 ; plus de « en principe »).
// Lot 10 (17/11/2026) : « avis_reponse », la réponse proposée envoyée au commerçant (admin_avis_proposer), garantie comme les autres.
const TYPES_ALERTE = ["avis_sensible", "avis_traite", "avis_recu", "avis_rappel_message", "avis_reponse"];
// Lot 8 : alertes garanties, par WhatsApp seulement (numéro obligatoire) : jamais d'email de secours ; un échec remonte à l'équipe (base).
const TYPES_GARANTIS = ["avis_sensible", "avis_recu", "avis_rappel_message", "avis_reponse"];
// Alertes auxquelles le commerçant répond (OK, ATTENDS, FAUX, correction) : elles portent la référence de l'avis (revue du 17/11/2026).
const REPONSE_ATTENDUE = ["avis_sensible", "avis_recu", "avis_rappel_message", "avis_reponse"];

// Valeurs communes au WhatsApp et à l'email : nom du commerce, note, prénom et initiale, extrait, lien vers l'écran des avis de l'espace.
function valeurs(el, ctx) {
  const lg = langueEmail(el.langue), note = Number(el.note);
  if (!TYPES_ALERTE.includes(el.type)) throw new Error("type d'alerte inconnu : " + el.type);
  const commerce = nettoyer(el.commerce).replace(/["<>]/g, "");
  if (!commerce) throw new Error("nom du commerce absent : alerte non rédigée");
  if (el.type !== "avis_sensible" && !(el.type === "avis_reponse" && el.sensible === true) && !(note >= 1 && note <= 5)) throw new Error("note de l'avis absente : alerte non rédigée");
  return { lg, commerce, note: note >= 1 && note <= 5 ? note : null, etoiles: note >= 1 && note <= 5 ? ETOILES[lg](note) : "", qui: prenomInitiale(el.auteur),
    extrait: el.type === "avis_traite" ? extrait(el.reponse) : "", equipe_repond: el.equipe_repond === true,
    texte: el.type === "avis_traite" ? "" : extrait(el.texte_avis, MAX_WHATSAPP), reponse: el.type === "avis_traite" ? "" : extrait(el.reponse, MAX_WHATSAPP),   // en entier (16/11/2026)
    poste: el.type === "avis_traite" ? "" : datePostee(el.ecrit_le, lg, el.pays),
    pasAvant: quandAnnonce(el.pas_avant, lg, ctx), sensible: el.sensible === true || el.type === "avis_sensible",
    ref: /^[A-Z][2-9][A-Z][2-9]?$/.test(String(el.ref || "")) ? String(el.ref) : "", auto: el.auto === true,
    // Contre-revue du 17/11/2026 : réponse renvoyée après un ATTENDS : aucune heure, publiée 48 h après sa demande sauf nouveau message.
    enAttente: el.type === "avis_reponse" && el.en_attente === true && !el.pas_avant,
    lien: adresse(ctx.urlEspace, /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(el.avis_id || "") ? "/#/avis?avis=" + String(el.avis_id).toLowerCase() : "/#/avis") };
}

function texteWhatsapp(el, ctx) {
  const x = valeurs(el, ctx), T = TEXTES_WA[x.lg];
  // Revue du 17/11/2026 : la référence de l'avis (« Réf. A7K ») sous l'en-tête de chaque alerte qui attend une réponse du commerçant.
  const avecRef = (y, l) => y.ref && REPONSE_ATTENDUE.includes(el.type) ? [l[0], T.ref(y.ref), ...l.slice(1)] : l;
  const rediger = y => avecRef(y, T[el.type](y)).filter(l => l !== null && l !== false).join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n\n" + T.signature;
  let t = rediger(x);
  // Filet de sécurité (MAX_WHATSAPP) : message trop long, l'avis puis la réponse proposée raccourcis du strict nécessaire, coupés à un mot.
  for (const k of ["texte", "reponse"]) {
    if (t.length <= MAX_WHATSAPP) break;
    if (x[k]) { x[k] = extrait(x[k], Math.max(80, x[k].length - (t.length - MAX_WHATSAPP))); t = rediger(x); }
  }
  return t;
}

function emailAlerte(el, ctx) {
  const x = valeurs(el, ctx), T = TEXTES_EMAIL[x.lg][el.type], M = MISE_EN_PAGE, mots = M.MOTS[x.lg];
  const chapo = typeof T.chapo === "function" ? T.chapo(x) : T.chapo;
  const sujet = T.sujet(x.commerce, x), ps = T.p(x).filter(Boolean), bonjour = { fr: "Bonjour,", en: "Hello,", nl: "Goeiedag," }[x.lg];
  const html = M.courriel({ lg: x.lg, titre: sujet, apercu: chapo, repere: x.commerce, h1: T.h1(x), chapo,
    corps: [M.p(echapper(bonjour), { couleur: M.C.texte }), ...ps.map(t => M.p(echapper(t))), M.bouton(x.lien, T.bouton)],
    pied: [mots.client(x.commerce)] });
  const texte = [bonjour, "", ...ps.flatMap(t => [t, ""]), T.bouton + (x.lg === "fr" ? " : " : ": ") + x.lien, "", mots.question, mots.equipe, "", mots.client(x.commerce)].join("\n");
  return { sujet, html, texte: avecPied(texte, x.lg) };
}

